#!/usr/bin/env python3
"""生成篆书回退所用的字符覆盖表，不改动主字库的原始缺字位掩码。"""
import json
from pathlib import Path

BASE = Path(__file__).resolve().parent.parent
SOURCES = {'yishan': 'coverage_zhuan.txt', 'shuowen': 'coverage_seal.txt'}


def main():
    coverage = {}
    for name, filename in SOURCES.items():
        chars = set((BASE / 'data' / filename).read_text(encoding='utf-8').strip())
        if not chars:
            raise ValueError(f'字体覆盖表为空：{filename}')
        coverage[name] = ''.join(sorted(chars))
    output = BASE / 'fonts' / 'seal-coverage.js'
    output.write_text(
        '// Generated by scripts/build_seal_coverage.py.\nconst SEAL_COVERAGE = '
        + json.dumps(coverage, ensure_ascii=False, separators=(',', ':')) + ';\n',
        encoding='utf-8',
    )
    print(f'{output.name}: ' + ', '.join(f'{name} {len(chars)} 字' for name, chars in coverage.items()))


if __name__ == '__main__':
    main()
